type auditorDocBehavior struct {
	Summary        string
	FindingKind    string
	RequiresEnrich bool
	PolicyFlags    []string
	Reasons        []string
}

func auditorBehavior(name string) auditorDocBehavior {
	switch name {
	case "vulnerability":
		return auditorDocBehavior{
			Summary:        "Evaluates the vulnerability records that matchers attached during `--enrich` against vulnerability policy.",
			FindingKind:    "vulnerability",
			RequiresEnrich: true,
			PolicyFlags:    []string{"--fail-on", "--allow-vulnerability-id"},
			Reasons:        []string{"severity threshold", "reachable symbol", "KEV listing"},
		}
	case "license":
		return auditorDocBehavior{
			Summary:        "Evaluates package licenses, read as SPDX expressions, against your allow and deny policy.",
			FindingKind:    "license",
			RequiresEnrich: false,
			PolicyFlags:    []string{"--allow-license", "--deny-license", "--license-exempt-package"},
			Reasons:        []string{"denied license", "license not in allowlist", "missing license"},
		}
	case "package":
		return auditorDocBehavior{
			Summary:        "Checks denied packages, suspiciously similar names, and dependency source changes, using data detectors already provide.",
			FindingKind:    "package",
			RequiresEnrich: false,
			PolicyFlags:    []string{"--deny-package", "--deny-group", "--protected-package", "--typosquat-threshold", "--typosquat-mode", "--fail-on source-change"},
			Reasons:        []string{"denied package", "denied group", "typosquat of protected package", "source changed to Git or URL"},
		}
	default:
		return auditorDocBehavior{
			Summary:        "Evaluates the dependency graph against policy and produces findings when `--audit` is set.",
			FindingKind:    "policy",
			RequiresEnrich: false,
			PolicyFlags:    nil,
			Reasons:        []string{"policy match"},
		}
	}
}

func humanAuditorTitle(name string) string {
	switch name {
	case "osv":
		return "OSV"
	default:
		return titleWords(strings.ReplaceAll(name, "-", " "))
	}
}

// matcherRunsByDefault reports whether the composition enables the named
// built-in matcher without an explicit --matchers selection. It reads the
// composition rather than keeping its own list: the two drifted once, and the
// generated page then described a default set the binary did not run.
func matcherRunsByDefault(name string) bool {
	for _, entry := range composition.Entries() {
		if entry.Kind == plugin.PluginKindMatcher && entry.Name == name {
			return entry.DefaultEnabled
		}
	}
	return false
}

// matcherDefaultSetMarkdown renders the sentence in the matcher guide that
// names the built-in matchers --enrich runs without a --matchers selection,
// and the ones that stay opt-in, from the composition. Installed external
// plugins are registered default-enabled too (internal/plugin), so the
// sentence says the list is the built-in set, not the whole run.
func matcherDefaultSetMarkdown() string {
	var enabled, optIn []string
	for _, entry := range composition.Entries() {
		if entry.Kind != plugin.PluginKindMatcher {
			continue
		}
		if entry.DefaultEnabled {
			enabled = append(enabled, entry.Name)
		} else {
			optIn = append(optIn, entry.Name)
		}
	}
	sort.Strings(enabled)
	sort.Strings(optIn)
	text := "With no `--matchers` selection, `--enrich` runs the built-in matchers " + codeList(enabled) + ", plus any installed external matcher plugin you have enabled."
	switch len(optIn) {
	case 0:
	case 1:
		text += " " + codeList(optIn) + " is opt-in: add it with `--matchers +" + optIn[0] + "`."
	default:
		text += " " + codeList(optIn) + " are opt-in: add one with `--matchers +<name>`."
	}
	return text
}

type matcherDocBehavior struct {
	Summary        string
	RequiresEnrich bool
	UsesNetwork    bool
	Cache          string
	OutputFields   []string
}

func matcherBehavior(name string) matcherDocBehavior {
	switch name {
	case "osv":
		return matcherDocBehavior{
			Summary:        "Looks up package vulnerabilities in OSV and attaches the matching advisories to packages.",
			RequiresEnrich: true,
			UsesNetwork:    true,
			Cache:          "Uses Bomly's matcher cache. Cache failures are warnings, not scan failures.",
			OutputFields:   []string{"vulnerability ID", "severity", "aliases", "CVSS", "fixed version", "references", "KEV signal"},
		}
	case "grype":
		return matcherDocBehavior{
			Summary:        "Runs Grype vulnerability matching against the resolved dependency graph. The full Bomly binary has Grype built in; the lite binary runs an external `grype` from `PATH`.",
			RequiresEnrich: true,
			UsesNetwork:    false,
			Cache:          "Relies on Grype's own local vulnerability database.",
			OutputFields:   []string{"vulnerability ID", "severity", "CVSS", "fixed version", "fix state", "EPSS", "CWE", "known exploitation", "risk score", "references"},
		}
	case "depsdev-license-matcher":
		return matcherDocBehavior{
			Summary:        "Fetches package metadata from deps.dev to fill in licenses the detector did not resolve.",
			RequiresEnrich: true,
			UsesNetwork:    true,
			Cache:          "Uses Bomly's matcher cache. Cache failures are warnings, not scan failures.",
			OutputFields:   []string{"license value", "license source", "matched package flag"},
		}
	case "scorecard":
		return matcherDocBehavior{
			Summary:        "Attaches the latest OpenSSF Scorecard run to packages whose source repository is on github.com. It is opt-in: select it with `--matchers +scorecard` next to `--enrich`. It needs no GitHub token because it reads precomputed runs from api.scorecard.dev.",
			RequiresEnrich: true,
			UsesNetwork:    true,
			Cache:          "Uses Bomly's matcher cache with a 24h TTL. Cache failures are warnings, not scan failures. Unscored repositories are cached too, so repeated runs do not ask for them again.",
			OutputFields:   []string{"scorecard.aggregateScore", "scorecard.checks[]", "scorecard.repository", "scorecard.runDate", "scorecard.scorecardVersion"},
		}
	default:
		return matcherDocBehavior{
			Summary:        "Enriches Bomly package data when `--enrich` selects it.",
			RequiresEnrich: true,
			UsesNetwork:    false,
			Cache:          "Matcher-specific.",
			OutputFields:   []string{"matcher-specific package metadata"},
		}
	}
}

func chainSupportsInstallFirst(detectors []string) bool {
	return slices.ContainsFunc(detectors, detectorSupportsInstallFirst)
}

func detectorSupportsInstallFirst(detectorName string) bool {
	reg := registry.NewRegistry(registry.Configs{}, *zap.NewNop())
	reg.Build()
	for _, descriptor := range reg.DetectorDescriptors() {
		if descriptor.Name == detectorName {
			return descriptor.SupportsInstallFirst
		}
	}
	return false
}

// builtinDetectorsByName indexes the built-in detector catalog by descriptor
// name for chain-level aggregation of recursive-discovery metadata.
func builtinDetectorsByName() map[string]plugin.Detector {
	detectors := registry.BuiltinDetectors()
	byName := make(map[string]plugin.Detector, len(detectors))
	for _, detector := range detectors {
		byName[detector.Descriptor().Name] = detector
	}
	return byName
}

// chainIgnoredDirectories unions the directory globs every detector in the
// chain declares as skipped during recursive discovery.
func chainIgnoredDirectories(detectors []string) []string {
	return chainIgnoredValues(detectors, func(descriptor plugin.DetectorDescriptor) []string {
		return descriptor.IgnoredDirectories
	})
}

// chainIgnoredDirectoryMarkers unions the marker files every detector in the
// chain declares as flagging an ignored directory during recursive discovery.
func chainIgnoredDirectoryMarkers(detectors []string) []string {
	return chainIgnoredValues(detectors, func(descriptor plugin.DetectorDescriptor) []string {
		return descriptor.IgnoredDirectoryMarkers
	})
}

func chainIgnoredValues(detectors []string, values func(plugin.DetectorDescriptor) []string) []string {
	byName := builtinDetectorsByName()
	seen := make(map[string]struct{})
	out := make([]string, 0)
	for _, detectorName := range detectors {
		detector, ok := byName[detectorName]
		if !ok {
			continue
		}
		for _, value := range values(detector.Descriptor()) {
			if _, ok := seen[value]; ok {
				continue
			}
			seen[value] = struct{}{}
			out = append(out, value)
		}
	}
	return out
}

// chainSupportsMultiModule reports whether any detector in the chain declares
// native multi-module (workspace/reactor) expansion for the package manager.
func chainSupportsMultiModule(detectors []string, manager model.PackageManager) bool {
	byName := builtinDetectorsByName()
	for _, detectorName := range detectors {
		detector, ok := byName[detectorName]
		if !ok {
			continue
		}
		supports := append(append([]plugin.PackageManagerSupport(nil), detector.Descriptor().PackageManagerSupport...), detector.PackageManagerSupport()...)
		for _, support := range supports {
			if support.MultiModule && support.PackageManager == manager {
				return true
			}
		}
	}
	return false
}

// commandHintsForChain renders the commands a chain may run. The bundled
// Syft needs no command, so its entry is a sentence about the lite build,
// which runs the external `syft` instead.
func commandHintsForChain(detectors []string) string {
	seen := make(map[string]struct{})
	values := make([]string, 0)
	syft := false
	for _, detector := range detectors {
		if detector == rootdetectors.NameSyft {
			syft = true
			continue
		}
		for _, command := range commandHintsForDetector(detector) {
			if _, ok := seen[command]; ok {
				continue
			}
			seen[command] = struct{}{}
			values = append(values, command)
		}
	}
	var parts []string
	if len(values) > 0 {
		parts = append(parts, codeList(values))
	}
	if syft {
		parts = append(parts, "The Syft fallback is built in; the lite build runs an external `syft` from `PATH` instead.")
	}
	if len(parts) == 0 {
		return "None"
	}
	return strings.Join(parts, ". ")
}

func commandHintsForDetector(detector string) []string {
	switch {
	case strings.Contains(detector, "npm"):
		return []string{"npm"}
	case strings.Contains(detector, "pnpm"):
		return []string{"pnpm"}
	case strings.Contains(detector, "yarn"):
		return []string{"yarn"}
	case detector == "go-detector" || strings.Contains(detector, "gomod"):
		return []string{"go"}
	case strings.Contains(detector, "maven"):
		return []string{"mvn"}
	case strings.Contains(detector, "gradle"):
		return []string{"gradle"}
	case strings.Contains(detector, "composer"):
		return []string{"composer"}
	case strings.Contains(detector, "bundler") || strings.Contains(detector, "ruby"):
		return []string{"bundle"}
	case strings.Contains(detector, "pipenv"):
		return []string{"pipenv"}
	case strings.Contains(detector, "poetry"):
		return []string{"poetry"}
	case strings.Contains(detector, "uv"):
		return []string{"uv"}
	case strings.Contains(detector, "pip"):
		return []string{"pip"}
	case strings.Contains(detector, "cargo"):
		return []string{"cargo"}
	case strings.Contains(detector, "nuget"):
		return []string{"dotnet"}
	case strings.Contains(detector, "mix"):
		return []string{"mix"}
	case strings.Contains(detector, "conan"):
		return []string{"conan"}
	case strings.Contains(detector, "pub"):
		return []string{"dart"}
	case strings.Contains(detector, "swiftpm"):
		return []string{"swift"}
	case strings.Contains(detector, "sbt"):
		return []string{"sbt"}
	default:
		return nil
	}
}

func ecosystemCodeList(values []model.Ecosystem) string {
	items := make([]string, 0, len(values))
	for _, value := range values {
		items = append(items, string(value))
	}
	return codeList(items)
}

func humanMatcherTitle(name string) string {
	switch name {
	case "osv":
		return "OSV"
	case "grype":
		return "Grype"
	case "depsdev-license-matcher":
		return "deps.dev license matcher"
	default:
		return titleWords(strings.ReplaceAll(name, "-", " "))
	}
}

func titleWords(value string) string {
	parts := strings.Fields(strings.ReplaceAll(value, "-", " "))
	for i, part := range parts {
		if part == "" {
			continue
		}
		parts[i] = strings.ToUpper(part[:1]) + part[1:]
	}
	return strings.Join(parts, " ")
}

func yesNo(value bool) string {
	if value {
		return "Yes"
	}
	return "No"
}

func writeMarkdown(path, content string) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return fmt.Errorf("create %s: %w", filepath.Dir(path), err)
	}
	if !strings.HasSuffix(content, "\n") {
		content += "\n"
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		return fmt.Errorf("write %s: %w", path, err)
	}
	return nil
}

// requirementCodeList renders a descriptor's declared requirements. A
// component that declares none gets no row: its requirements are
// unspecified, which the absence of the row already says.
func requirementCodeList(requires plugin.Requirements) string {
	values := make([]string, 0, len(requires))
	for _, requirement := range requires.Normalized() {
		values = append(values, string(requirement))
	}
	return codeList(values)
}

// chainRequirements renders the requirements each detector in a chain
// declares, as "detector: tokens" entries; empty when none declares any.
func chainRequirements(detectorNames []string) string {
	byName := builtinDetectorsByName()
	var entries []string
	for _, name := range detectorNames {
		detector, ok := byName[name]
		if !ok || len(detector.Descriptor().Requires) == 0 {
			continue
		}
		entries = append(entries, fmt.Sprintf("`%s`: %s", name, requirementCodeList(detector.Descriptor().Requires)))
	}
	return strings.Join(entries, "; ")
}
